import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { completeCartWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await completeCartWorkflow(req.scope)
    .run({
      input: {
        id: "cart_123"
      }
    })

  res.send(result)
}

